<script setup lang="ts">import {ref} from 'vue';import {useAuthStore} from '@/stores/auth';import {useRouter} from 'vue-router';import {messageOf} from '@/lib/api';const email=ref('admin@auditor.local'),password=ref('ChangeMe!123'),error=ref(''),loading=ref(false),auth=useAuthStore(),router=useRouter();async function login(){loading.value=true;error.value='';try{await auth.login(email.value,password.value);router.push('/')}catch(e){error.value=messageOf(e)}finally{loading.value=false}}</script><template><div class="login-page"><form class="login-card" @submit.prevent="login"><div class="brand login-brand"><div class="brand-mark">AF</div><div><strong>Auditor Fiscal</strong><small>IBS/CBS e Reforma Tributária</small></div></div><h2>Acesso seguro</h2><label>E-mail<input v-model="email" type="email" autocomplete="username" required/></label><label>Senha<input v-model="password" type="password" autocomplete="current-password" required/></label><p class="error" v-if="error">{{error}}</p><button class="primary" :disabled="loading">{{loading?'Entrando...':'Entrar'}}</button></form></div></template>
